    / activate() is a no-op in the entitlement model — premium is admin-granted server-side. /
    fun activate(
        macroId: Any?,
        key: Any?,
        secret: Any?,
    ): Int = if (isActive()) 1 else 0

    fun isValid(
        macroId: Any?,
        secret: Any?,
    ): Boolean = isActive(macroId, secret)

    fun daysLeft(macroId: Any?): Int = if (isEntitled()) Int.MAX_VALUE else 0

    / deactivate() is a no-op — only admin can revoke. TODO: expression return requires manual bridge tracing; return kept as any.

Sets the humanize level (clamped to 0..3) for the active macro. Returns the stored level. /
    fun setLevel(value: Any?): Int {
        val requested = value.toIntCompat(HumanizeGesturePolicy.LEVEL_OFF)
        val sanitized = requested.coerceIn(0, MAX_LEVEL)
        val macroId = activeMacroIdProvider()?.trim().orEmpty()
        if (macroId.isEmpty()) {
            logger("Humanize.setLevel: aktif makro yok, seviye kaydedilmedi.")
            return HumanizeGesturePolicy.LEVEL_OFF
        }
        val stored = writeLevel(macroId, sanitized)
        if (requested != sanitized) {
            logger("Humanize.setLevel: deger 0-$MAX_LEVEL araligina sabitlendi ($requested -> $sanitized).")
        }
        return stored
    }

    / Current humanize level for the active macro (0 when no macro context).

