    /
      Linear RGB interpolation between this colour and [other].
      `ratio = 0` returns `this`, `ratio = 1` returns `other`, anything in
      between produces a proportional blend. Alpha is mixed on the same axis.
     /
    fun mix(other: CompatColor, ratio: Any?): CompatColor {
        val t = numericTolerance(ratio, 0.5, max = 1.0)
        val blended = mixWithComponents(other.r, other.g, other.b, t)
        val newA = (a + (other.a - a)  t).toInt().coerceIn(0, 255)
        return blended.copy(a = newA)
    }

